const saida = [];
for (const i of items) {
  const fonte = i.json;
  const payload = i.json.content || i.json.data || i.json.items || i.json;
  const arr = Array.isArray(payload) ? payload : [payload];
  for (const row of arr) {
    saida.push({ json: { fonte, payload: row } });
  }
}
return saida;

function pick(obj, paths, fallback = null) { for (const path of paths) { const parts = path.split('.'); let value = obj; let ok = true; for (const p of parts) { if (value && Object.prototype.hasOwnProperty.call(value, p)) value = value[p]; else { ok = false; break; } } if (ok && value !== undefined && value !== null && value !== '') return value; } return fallback; }
function onlyDigits(v) { return String(v || '').replace(/\D/g, ''); }
function toNumber(value) { if (typeof value === 'number') return value; if (!value) return 0; const normalized = String(value).replace(/R\$\s?/g, '').replace(/\./g, '').replace(',', '.').trim(); const n = Number(normalized); return Number.isFinite(n) ? n : 0; }
function toISODate(v) { if (!v) return null; const str = String(v).trim(); if (/^\d{4}-\d{2}-\d{2}/.test(str)) return str.slice(0, 10); const br = str.match(/^(\d{2})\/(\d{2})\/(\d{4})$/); if (br) return `${br[3]}-${br[2]}-${br[1]}`; return null; }
function buildId(raw, fonte) { const base = pick(raw, ['id', 'id_transacao', 'hash']) || `${pick(raw, ['numero_empenho', 'num_empenho', 'numero'], 'sem_numero')}:${pick(raw, ['data_empenho', 'dt_emissao', 'data_gasto'], 'sem_data')}:${pick(raw, ['valor_empenhado', 'valor_pago', 'total'], '0')}:${fonte?.municipio_ibge || '0000000'}`; return `${fonte?.id || 'fonte'}:${String(base).slice(0, 180)}`; }
const out = [];
for (const item of items) { const fonte = item.json.fonte || {}; const raw = item.json.payload || item.json; out.push({ json: { id_transacao: buildId(raw, fonte), fonte_id: fonte.id || null, data_empenho: toISODate(pick(raw, ['data_empenho','dataEmpenho','dt_emissao','data_gasto'])), valor_empenhado: toNumber(pick(raw, ['valor_empenhado','valorEmpenho','valor_pago','total'], 0)), favorecido_nome: pick(raw, ['favorecido_nome','fornecedor.nomeRazaoSocial','credor','razao_social'], 'NAO INFORMADO'), favorecido_cnpj_cpf: onlyDigits(pick(raw, ['favorecido_cnpj_cpf','fornecedor.cpfCnpj','cpf_cnpj'], '')), elemento_despesa: String(pick(raw, ['elemento_despesa','elementoDespesa.codigo'], '')).replace(/\./g, ''), funcao_governo: pick(raw, ['funcao_governo','funcao.descricao'], null), municipio_nome: fonte.municipio_nome || pick(raw, ['municipio','cidade_nome'], null), municipio_ibge: String(fonte.municipio_ibge || pick(raw, ['municipio_ibge'], '')).padStart(7, '0'), uf: String(fonte.uf || pick(raw, ['uf'], '')).toUpperCase().slice(0,2), fornecedor_sistema: fonte.sistema_fornecedor || null, url_origem: fonte.url_base || null, payload_origem: raw } }); }
return out;

const out = [];
for (const item of items) {
  const j = item.json;
  let parsed = { categoria_ia: 'nao_classificado', risco_ia: 'medio', justificativa_ia: 'IA indisponivel' };
  try {
    const txt = j.output?.[0]?.content?.[0]?.text;
    if (txt) parsed = JSON.parse(txt);
  } catch (_e) {}
  out.push({ json: { ...j, ...parsed } });
}
return out;
